/* eslint-disable check-file/filename-naming-convention */
import { createContext } from 'react';

import type { AttributeRenameMigrationMode } from './RenameMigrationModal';
import type { ContentStructure, FolderSelection, SectionKey } from './utils/contentStructure';
import type { Component, ContentType } from '../../types';
import type { ComponentWithChildren } from './utils/retrieveComponentsThatHaveComponents';
import type { NestedComponent } from './utils/retrieveNestedComponents';
import type { Internal, Struct } from '@strapi/types';

export interface DataManagerContextValue {
  isLoading: boolean;
  addAttribute: (opts: {
    attributeToSet: Record<string, unknown>;
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
  }) => void;
  editAttribute: (opts: {
    attributeToSet: Record<string, unknown>;
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    name: string;
    recordRename?: boolean;
    declineRename?: boolean;
    recordTargetRename?: boolean;
    declineTargetRename?: boolean;
  }) => void;
  moveAttribute: (opts: {
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    from: number;
    to: number;
  }) => void;
  addCustomFieldAttribute: (params: {
    attributeToSet: Record<string, unknown>;
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
  }) => void;
  editCustomFieldAttribute: (params: {
    attributeToSet: Record<string, unknown>;
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    name: string;
    recordRename?: boolean;
    declineRename?: boolean;
  }) => void;
  /**
   * Resolves the user's consent to preserve data for one rename hop performed
   * in the attribute form: `true` records the hop, `false` declines it (and the
   * rest of its chain), `null` means the user cancelled the edit.
   */
  confirmAttributeRenameMigration: (rename: {
    forTarget: Struct.ModelType;
    uid: Internal.UID.Schema;
    oldName: string;
    newName: string;
  }) => Promise<boolean | null>;
  /** Effective `renameMigrations.attributes` plugin setting. */
  attributeRenameMigrationMode: AttributeRenameMigrationMode;
  addCreatedComponentToDynamicZone: (opts: {
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    dynamicZoneTarget: string;
    componentsToAdd: Internal.UID.Component[];
  }) => void;
  createComponentSchema: (opts: {
    data: {
      icon?: string;
      displayName: string;
    };
    componentCategory: string;
    uid: Internal.UID.Component;
  }) => void;
  createSchema: (opts: {
    data: {
      displayName: string;
      singularName: string;
      pluralName: string;
      kind: Struct.ContentTypeKind;
      draftAndPublish: boolean;
      pluginOptions: Record<string, unknown>;
    };
    uid: Internal.UID.Schema;
    folder?: FolderSelection;
  }) => void;
  changeDynamicZoneComponents: (opts: {
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    dynamicZoneTarget: string;
    newComponents: Internal.UID.Component[];
  }) => void;
  removeAttribute: (opts: {
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    attributeToRemoveName: string;
  }) => void;
  deleteComponent(uid: Internal.UID.Component): void;
  deleteContentType(uid: Internal.UID.ContentType): void;
  contentStructure: ContentStructure;
  createFolder: (opts: { section: SectionKey; name: string; parentId: string | null }) => void;
  renameFolder: (opts: { section: SectionKey; id: string; name: string }) => void;
  moveFolder: (opts: {
    section: SectionKey;
    id: string;
    newParentId: string | null;
    index?: number;
  }) => void;
  deleteFolderOnly: (opts: { section: SectionKey; id: string }) => void;
  deleteFolderAndContent: (opts: {
    section: SectionKey;
    id: string;
    contentTypeUids: Internal.UID.ContentType[];
  }) => void;
  assignContentTypeToFolder: (opts: {
    section: SectionKey;
    uid: Internal.UID.ContentType;
    targetGroupId: string | null;
    index?: number;
  }) => void;
  reorderFolderChildren: (opts: {
    section: SectionKey;
    groupId: string;
    from: number;
    to: number;
  }) => void;
  removeComponentFromDynamicZone: (opts: {
    forTarget: Struct.ModelType;
    targetUid: Internal.UID.Schema;
    dzName: string;
    componentToRemoveIndex: number;
  }) => void;
  sortedContentTypesList: {
    visible: ContentType['visible'];
    name: ContentType['uid'];
    title: ContentType['info']['displayName'];
    plugin: ContentType['plugin'];
    uid: ContentType['uid'];
    to: string;
    kind: ContentType['kind'];
    restrictRelationsTo: ContentType['restrictRelationsTo'];
    status: ContentType['status'];
  }[];
  updateComponentSchema: (opts: {
    data: {
      icon?: string;
      displayName: string;
    };
    componentUID: Internal.UID.Component;
  }) => void;
  updateComponentUid: (opts: {
    newComponentUID: Internal.UID.Component;
    componentUID: Internal.UID.Component;
  }) => void;
  updateSchema: (opts: {
    data: {
      displayName: string;
      kind: Struct.ContentTypeKind;
      draftAndPublish: boolean;
      pluginOptions: Record<string, unknown>;
    };
    uid: Internal.UID.ContentType;
    folder?: FolderSelection;
  }) => void;
  initialComponents: Record<Internal.UID.Component, Component>;
  components: Record<Internal.UID.Component, Component>;
  componentsGroupedByCategory: Record<string, Component[]>;
  componentsThatHaveOtherComponentInTheirAttributes: ComponentWithChildren[];
  initialContentTypes: Record<Internal.UID.ContentType, ContentType>;
  contentTypes: Record<Internal.UID.ContentType, ContentType>;
  isInDevelopmentMode?: boolean;
  nestedComponents: NestedComponent[];
  reservedNames: {
    models: string[];
    attributes: string[];
  };
  allComponentsCategories: string[];
  saveSchema(): Promise<void>;
  isModified: boolean;
  isSaving: boolean;
  /**
   * Applies a whole-type change (AI chat). Rename hops declared by the change
   * go through the same preservation consent as manual renames, so this may
   * prompt the user. Resolves `false` when the user cancelled and nothing was
   * applied.
   */
  applyChange: (opts: {
    action: 'add' | 'update' | 'delete';
    schema: ContentType | Component;
  }) => Promise<boolean>;
  history: {
    undo(): void;
    redo(): void;
    discardAllChanges(): void;
    canUndo: boolean;
    canRedo: boolean;
    canDiscardAll: boolean;
  };
}

// @ts-expect-error need to pass initial value to params
export const DataManagerContext = createContext<DataManagerContextValue>();
